import type { Fact, WalkStep } from '@/app/demos/stage/types'

import { pick, seeded } from '../_shared'

export const TABS = ['Number', 'String', 'Hex', 'UUID', 'NanoID'] as const
export const DEFAULT_TAB = TABS.indexOf('String')
export const MIN = 1
export const MAX = 100
export const LENGTH = 16

const ALPHANUMERIC = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
const HEX = '0123456789abcdef'
export const NANOID_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-'

const random = seeded(7)

function uuidV4() {
  const hex = pick(random, HEX, 32).split('')
  hex[12] = '4'
  hex[16] = '89ab'[Math.floor(random() * 4)]
  const value = hex.join('')
  return `${value.slice(0, 8)}-${value.slice(8, 12)}-${value.slice(12, 16)}-${value.slice(16, 20)}-${value.slice(20)}`
}

export const ROLLS = [
  {
    tab: TABS.indexOf('Number'),
    value: String(MIN + Math.floor(random() * (MAX - MIN + 1))),
    chars: '0123456789',
  },
  { tab: TABS.indexOf('String'), value: pick(random, ALPHANUMERIC, LENGTH), chars: ALPHANUMERIC },
  {
    tab: TABS.indexOf('Hex'),
    value: pick(random, HEX, LENGTH),
    chars: HEX,
  },
  { tab: TABS.indexOf('UUID'), value: uuidV4(), chars: HEX },
  {
    tab: TABS.indexOf('NanoID'),
    value: pick(random, NANOID_ALPHABET, LENGTH),
    chars: NANOID_ALPHABET,
  },
]

